package com.codearena.security;
import com.codearena.user.User; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; private final long accessTtl,refreshTtl; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.access-ttl-seconds}") long a,@Value("${app.jwt.refresh-ttl-seconds}") long r){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));accessTtl=a;refreshTtl=r;} private String token(User u,long ttl,String type){var now=Instant.now();var roleNames=new ArrayList<String>();for(var role:u.roles)if(role!=null)roleNames.add(role.name());return Jwts.builder().subject(u.id.toString()).claim("roles",roleNames).claim("typ",type).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(ttl))).signWith(key).compact();} public String access(User u){return token(u,accessTtl,"access");} public String refresh(User u){return token(u,refreshTtl,"refresh");} public Claims parse(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload();} public long refreshTtlSeconds(){return refreshTtl;} }
